#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-06

# strict-mode: opt-out sourced library; the caller sets its own strict mode and
# this runner must observe probe exit codes rather than die on them.
#
# Shared runner for tests/<dir>/fault-arms/*.sh (gate-fault-arm audit,
# docs/audits/gate-fault-arm-audit-2026-09-06.md).
#
# Every probe under fault-arms/ builds its own fixtures, runs one gate with the
# input PRESENT (control) and again with it ABSENT, EMPTY, or MIS-ROOTED
# (fault, fault2, ...), and prints one line:
#   RESULT gate=<slug> control=<rc> fault=<rc> [fault2=<rc> ...] [key=value ...]
# The contract asserted here: control MUST be 0 and every fault* MUST be
# non-zero, except arms listed in the caller's BY_DESIGN allowlist ("slug:arm"),
# which are documented cases where an absent input is the correct state.
#
# Usage (from a test-*.sh next to a fault-arms/ dir):
#   source "$REPO_ROOT/tests/fixtures/run-fault-arms.sh"
#   BY_DESIGN=("manifest-dependencies:fault2")
#   run_fault_arms "$SCRIPT_DIR/fault-arms"
#
# Not named test-*.sh on purpose: scripts/ci/run-tests.sh globs that pattern,
# and this file is a library.

run_fault_arms() {
    local dir="$1"
    local repo_root
    repo_root="$(cd "$dir/../../.." && pwd)"
    local harness
    harness="$(mktemp -d "${TMPDIR:-/tmp}/ork-fault-arms.XXXXXX")"
    mkdir -p "$harness/fixtures"

    # Probes build throwaway git repos (`git init`, `git add -A` in a fixture
    # dir). Under a git hook the environment carries GIT_INDEX_FILE (absolute in
    # a linked worktree) and can carry GIT_DIR / GIT_WORK_TREE; a nested `git`
    # then writes the FIXTURE's tree into the REAL index. Measured 2026-09-06 in
    # .worktrees/skill-dir-codemod: one pre-commit run left 2 of 6947 entries
    # (src/offender.sh and the copied gate) and staged 6945 deletions. Scrub
    # every repo-locating GIT_* variable so each probe sees only its own cwd.
    unset GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_PREFIX GIT_COMMON_DIR \
        GIT_OBJECT_DIRECTORY GIT_ALTERNATE_OBJECT_DIRECTORIES

    local pass=0 fail=0 n=0
    for probe in "$dir"/*.sh; do
        [[ -f "$probe" ]] || continue
        n=$((n + 1))
        local slug line
        slug="$(basename "$probe" .sh)"
        line="$(REPO="$repo_root" H="$harness" bash "$probe" 2>"$harness/$slug.err" | grep '^RESULT ' | tail -1)"
        if [[ -z "$line" ]]; then
            echo "  FAIL: $slug printed no RESULT line (stderr: $(tail -2 "$harness/$slug.err" | tr '\n' ' '))"
            fail=$((fail + 1))
            continue
        fi
        local ok=1 kv key val
        for kv in $line; do
            case "$kv" in
                control=*|*_control=*|fault*=*|*_fault*=*) key="${kv%%=*}"; val="${kv#*=}" ;;
                *) continue ;;
            esac
            if [[ "$key" == "control" || "$key" == *_control ]]; then
                if [[ "$val" != "0" ]]; then
                    echo "  FAIL: $slug control arm exited $val (want 0)"; ok=0
                fi
            elif [[ "$val" == "0" ]]; then
                if _by_design "$slug:$key"; then
                    echo "  note: $slug $key exited 0 by design (documented absent-input state)"
                else
                    echo "  FAIL: $slug $key arm exited 0 (the gate passed on absent input)"; ok=0
                fi
            elif [[ "$val" == "na" ]]; then
                echo "  note: $slug $key not exercised"
            fi
        done
        if [[ $ok -eq 1 ]]; then
            echo "  PASS: $line"
            pass=$((pass + 1))
        else
            echo "        $line"
            fail=$((fail + 1))
        fi
    done

    rm -rf "$harness"
    echo ""
    echo "Fault arms: $pass passed, $fail failed (of $n probes)"
    if [[ $n -eq 0 ]]; then
        echo "FAIL: no probes found under $dir; this runner had nothing to run"
        return 1
    fi
    [[ $fail -eq 0 ]]
}

_by_design() {
    local needle="$1" item
    for item in "${BY_DESIGN[@]:-}"; do
        [[ "$item" == "$needle" ]] && return 0
    done
    return 1
}
